const originalScopes=new WeakSet(),originalEmbeddings=new WeakMap(),originalIndexes=new WeakMap(),originalReferences=new WeakMap(),originalReviewers=new WeakSet();
export const KNOWLEDGE_APPLICATION_ABI='craft.knowledge-application-ports/v1';
const loadedKnowledgeSha256=sha256(readFileSync(new URL(import.meta.url)));
function selectedKnowledgeArtifact(artifact){const captured=inspectGenericNativeProfileArtifact(artifact),file=captured.files.find(f=>f.path==='native/application/knowledge.mjs');assert(captured.name==='@craft/ai-profiles'&&file?.sha256===loadedKnowledgeSha256,'ForeignOwner','actual loaded knowledge implementation matches original selected artifact');return ()=>{assertGenericNativeProfileArtifact(artifact);assert(sha256(readFileSync(new URL(import.meta.url)))===loadedKnowledgeSha256,'StaleOwner','loaded knowledge module changed');};}

const stageContracts=freeze({
 'ingestion.prepare':{kind:'index',abi:'craft.knowledge-index-port/v1',method:'prepare',binding:'PrepareKnowledge'},
 'ingestion.activate':{kind:'index',abi:'craft.knowledge-index-port/v1',method:'activate',binding:'ActivateKnowledge'},
 'rag.decide':{kind:'document',abi:KNOWLEDGE_APPLICATION_ABI,method:'validateAnswer',binding:'ValidateKnowledgeAnswer'},
 'rag.release':{kind:'document',abi:'craft.knowledge-cache/v1',method:'release',binding:'ReleaseKnowledgeAnswer'},
 'ingestion.retire.review':{kind:'document',abi:KNOWLEDGE_APPLICATION_ABI,method:'reviewRetirement',binding:'ReviewKnowledgeRetirement'},
 'ingestion.retire':{kind:'document',abi:KNOWLEDGE_APPLICATION_ABI,method:'retire',binding:'RetireKnowledge'},
 'support.review':{kind:'document',abi:KNOWLEDGE_APPLICATION_ABI,method:'reviewReply',binding:'ReviewKnowledgeReply'},
});
/** Pure compiler operand resolution from ORIGINAL captured installed bytes and
 * actual authored source/config files, never caller-entered digest strings. */
export function knowledgeApplicationStageIdentity({artifact,operation,businessSourcePath,sourceConfigurationPath,representation}){
 const installed=inspectGenericNativeProfileArtifact(artifact),contract=stageContracts[operation];assert(installed.name==='@craft/ai-profiles'&&contract&&installed.files.some(f=>f.path==='native/application/knowledge.mjs'),'UnsupportedCapability','actual selected knowledge implementation');
 const source=readFileSync(businessSourcePath),module=new TextDecoder('utf8',{fatal:true}).decode(source).match(/^module ([A-Za-z_][A-Za-z0-9_]*) version 1\r?\n/)?.[1];assert(module,'InvalidContract','actual business module');
 const configuration=readFileSync(sourceConfigurationPath),logical={schema:'craft.knowledge-stage-contract/v1',operation,...contract,module,input:module+'.ProfileStageWork',result:module+'.ProfileStageOutput',business_sha256:sha256(source),source_configuration_sha256:sha256(configuration)},realization={schema:'craft.knowledge-stage-realization/v1',operation,abi:contract.abi,method:contract.method,parser:PARSER_IDENTITY,index:RETRIEVAL_IDENTITY,...(representation?{representation:capture(representation)}:{})},provider_lineage={resource_ref:module+'.'+contract.binding,provider:'owned-local-knowledge',api_revision:contract.abi};
 const identity={contract_sha256:sha256(canonical(logical)),realization_sha256:sha256(canonical(realization)),provider_lineage,implementation_sha256:installed.sha256};
 return freeze({operation,kind:contract.kind,bindingId:module+'.'+contract.binding,capability_sha256:sha256(canonical(identity)),identity,implementation:{package:installed.name,version:installed.version,sha256:installed.sha256,export:'./application/knowledge'},contract:logical,realization});
}
const bytes=value=>new TextEncoder().encode(canonical(value));
const copy=value=>JSON.parse(canonical(value));
const port=(value,abi,methods)=>assert(value?.abi===abi&&methods.every(k=>typeof value[k]==='function'),'ForeignOwner','original '+abi+' required');
const snapshotMatch=(actual,expected)=>assert(actual.id===expected.id&&actual.tenant===expected.tenant&&actual.revision===expected.version&&actual.aclRevision===expected.aclRevision&&actual.sha256===expected.sha256,'StaleOwner','original source/version/ACL/content changed');
const candidate=(outcome)=>{assert(outcome?.kind==='candidate'&&outcome.wire instanceof Uint8Array,'OutcomeUnknown','original typed model candidate required');return outcome;};
export function createKnowledgeExecutionScope(){const storage=new AsyncLocalStorage();const resource=Object.freeze({run:async(value,work)=>storage.run(value,work),current(){const s=storage.getStore();assert(s&&typeof s.assertCurrent==='function','ForeignOwner','original active knowledge invocation');s.assertCurrent();return s;}});originalScopes.add(resource);return resource;}
export function createKnowledgeQualityReviewer({evaluate}){assert(typeof evaluate==='function','InvalidContract','trusted independent reviewer');const resource=Object.freeze({identity:Object.freeze({abi:'craft.knowledge-quality-reviewer/v1',id:'knowledge-independent-review/v1'}),async evaluate(input){const independent={query:input.query??'',proposal:input.proposal===undefined?null:freeze(capture(input.proposal)),wire:input.wire===undefined?new Uint8Array():copyBytes(input.wire,32768),evidence:freeze(capture(input.evidence))};const output=capture(await evaluate(independent));assert(Object.keys(output).sort().join(',')==='answerSupported,injectionDetected,supportingSources'&&typeof output.answerSupported==='boolean'&&typeof output.injectionDetected==='boolean'&&Array.isArray(output.supportingSources)&&output.supportingSources.length<=16&&new Set(output.supportingSources).size===output.supportingSources.length,'InvalidContract','bounded independent review labels');const available=new Set(input.evidence.map(row=>row.sourceId));for(const id of output.supportingSources){text(id);assert(available.has(id),'InvalidContract','reviewer labels selected actual evidence only');}return freeze(output);}});originalReviewers.add(resource);return resource;}
export function inspectKnowledgeResources({scope,index,documents,release,representation,queryEmbeddings,ingestion,quality}){assert(originalScopes.has(scope),'ForeignOwner','original knowledge execution scope');assertOriginalDocumentPort(documents,{releaseAuthority:release.authority});const owned=originalIndexes.get(index);assert(owned&&owned.documents===documents&&owned.scope===scope.current,'ForeignOwner','same original index/document/scope');const retrieval=inspectOriginalRetrieval(owned.retrieval);assert(retrieval.documentPort===documents&&retrieval.parser===owned.parser,'ForeignOwner','same original retrieval dependencies');assertOriginalDocumentParser(owned.parser);const checkEmbedding=port=>{const original=originalEmbeddings.get(port);assert(original&&original.documentPort===documents&&original.context===scope.current&&original.release===release&&canonical(original.identity)===canonical(representation),'ForeignOwner','original embedding/source/release/scope/representation');original.current();};checkEmbedding(retrieval.embeddingPort);assert(canonical(retrieval.profile.representation)===canonical(representation),'ForeignOwner','original index representation');if(queryEmbeddings)checkEmbedding(queryEmbeddings);if(ingestion){const reference=originalReferences.get(ingestion.port);assert(reference&&reference.documents===documents&&reference.retrieval===owned.retrieval&&reference.release===release.port,'ForeignOwner','original generated ingestion reference and same index');assert(reference.references.has(ingestion.reference),'ForeignOwner','genuine opaque ingestion reference');}if(quality)assert(originalReviewers.has(quality),'ForeignOwner','original selected independent reviewer');return Object.freeze({retrieval:owned.retrieval});}

/** A tiny technical observation receipt index, not a workflow/effect queue.
 * Original M00/R02 owners alone dispatch/account. Unknown mappings never retry. */
export function createKnowledgeEmbeddingPort({path,inference,codec,release,documentPort,context,representation,policyId,bindingId='Knowledge.Embedding',now=Date.now}){
 text(path,'embedding receipt path',4096);port(inference,'inference-port/v1',['invoke','inspectAttempt','inspectInvocation','assertCurrent']);port(documentPort,'craft.document-authority/v1',['read']);
 assert(release?.authority&&release?.port?.abi==='source-release-port/v1'&&typeof context==='function'&&typeof codec?.decode==='function'&&codec.schema?.minItems===1536&&codec.schema?.maxItems===1536,'ForeignOwner','original generated vector codec/release/scope required');
 const db=new DatabaseSync(path);db.exec('PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS knowledge_embedding_receipts(id TEXT PRIMARY KEY,request TEXT NOT NULL,attempt TEXT,state TEXT NOT NULL,vector TEXT) STRICT;');let closed=false;
 for(const k of ['model','preprocessing','space'])text(representation?.[k],k);assert(representation.dimensions===1536,'UnsupportedCapability','qualified embedding representation');
 const identity=freeze(capture(representation));
 const current=()=>{assert(!closed,'StaleOwner','embedding receipt owner closed');inference.assertCurrent();documentPort.assertCurrent?.();};
 const requestData=r=>{text(r.observationId,'observationId');assert(typeof r.text==='string'&&r.text.isWellFormed()&&Buffer.byteLength(r.text)<=8192,'InvalidContract','bounded literal parsed chunk text');assert(canonical(r.representation)===canonical(identity),'UnsupportedCapability','exact selected embedding representation');const scope=context();assert(scope.tenant===r.source.tenant&&typeof scope.assertCurrent==='function','ForeignOwner','original embedding tenant/scope');scope.assertCurrent();snapshotMatch(documentPort.read({id:r.source.id,tenant:r.source.tenant,principal:scope.principal}),r.source);return {scope,body:canonical({text:r.text,source:r.source,representation:r.representation})};};
 const invocation=(r,scope)=>{const contextId='embedding:'+r.observationId;release.authority.defineContext({id:contextId,tenant:scope.tenant,principal:scope.principal,inputs:[{adapter:documentPort.adapterId,id:r.source.id}]});const manifest=release.port.captureContext({contextId,tenant:scope.tenant,principal:scope.principal});return {intentId:'embedding:'+r.observationId,bindingId,operation:'vector.embed',input:new TextEncoder().encode(r.text),result_schema:codec.schema,decodeResult:codec.decode,deadline_ms:Math.min(scope.deadline_ms,now()+300000),limits:{max_input_bytes:65536,max_output_bytes:65536,max_model_attempts:1,max_tool_calls:0},context:{tenant:scope.tenant,principal:scope.principal,fence:scope.fence,approvalRevision:scope.approvalRevision,sourceRevision:r.source.version,manifest,policyId}};};
 const inspect=async r=>{current();const {scope,body}=requestData(r),row=db.prepare('SELECT * FROM knowledge_embedding_receipts WHERE id=?').get(r.observationId);assert(!row||row.request===body,'InvalidContract','immutable embedding observation input');
  if(!row){const observed=await inference.inspectInvocation(invocation(r,scope));return freeze({status:observed.kind==='not-dispatched'?'definitively-no-effect':'unknown'});}
  if(!row.attempt)return freeze({status:'unknown'});
  const observation=inference.inspectAttempt(row.attempt).observation;
  if(observation?.kind!=='confirmed'||observation.result?.kind!=='candidate')return freeze({status:'unknown'});
  const checked=await codec.decode(Uint8Array.from(observation.result.wire));scope.assertCurrent();requestData(r);assert(checked.ok&&Array.isArray(checked.value),'InvalidVector','original generated embedding result');
  return {status:'confirmed',vector:checked.value,observationId:r.observationId,attemptId:row.attempt};
 };
 const resource=Object.freeze({identity,async embed(r){current();const {scope,body}=requestData(r),old=db.prepare('SELECT * FROM knowledge_embedding_receipts WHERE id=?').get(r.observationId);
   if(old){assert(old.request===body,'InvalidContract','immutable original embedding intent');const recovered=await inspect(r);assert(recovered.status==='confirmed','OutcomeUnknown','original embedding inspection required; no repeated paid call');return recovered;}
   // Written before paid dispatch: a crash without returned attempt identity is
   // conservatively unknown, rather than a guessed definitely-no-effect retry.
   db.prepare("INSERT INTO knowledge_embedding_receipts VALUES(?,?,NULL,'prepared',NULL)").run(r.observationId,body);
   const result=await inference.invoke(invocation(r,scope));
   if(result.attemptId)db.prepare('UPDATE knowledge_embedding_receipts SET attempt=?,state=? WHERE id=?').run(result.attemptId,result.kind,r.observationId);
   scope.assertCurrent();requestData(r);candidate(result);assert(Array.isArray(result.value),'InvalidVector','technical embedding vector only');
   db.prepare("UPDATE knowledge_embedding_receipts SET state='confirmed',vector=? WHERE id=?").run(canonical(result.value),r.observationId);
   return {status:'confirmed',vector:result.value,observationId:r.observationId,attemptId:result.attemptId};
  },inspect,close(){if(!closed){closed=true;db.close();}}});originalEmbeddings.set(resource,{documentPort,release,context,identity,current});return resource;
}

/** Source-approved index preparation/activation split. The application calls
 * prepare, evaluates its authored Operation, then chooses its declared activate
 * stage. No native code duplicates the domain activation predicate. */
export function createKnowledgeIndexPort({documents,retrieval,parser,scope}){
 port(documents,'craft.document-authority/v1',['read','beginGeneration','recoverGeneration','inspectGeneration','activeGeneration']);assert(retrieval?.identity?.abi===RETRIEVAL_IDENTITY.abi&&typeof retrieval.activate==='function'&&parser?.identity?.abi===PARSER_IDENTITY.abi&&typeof scope==='function','ForeignOwner','original parser/retrieval/scope');
 const generations=new WeakMap();
 const handle=(generation,tenant)=>{const h=Object.freeze({kind:'knowledge-generation/v1',id:generation.id});generations.set(h,{generation,tenant});return h;};
 const owned=h=>{const r=generations.get(h);assert(r,'ForeignOwner','original generation handle');scope().assertCurrent();return r;};
 const resource=Object.freeze({abi:'craft.knowledge-index-port/v1',
  async parse({id}){const s=scope();s.assertCurrent();const source=documents.read({id,tenant:s.tenant,principal:s.principal}),parsed=await parser.parse({bytes:source.bytes,mediaType:source.mediaType,source:{tenant:s.tenant,sourceId:id,version:source.revision}});s.assertCurrent();snapshotMatch(documents.read({id,tenant:s.tenant,principal:s.principal}),{id,tenant:s.tenant,version:source.revision,aclRevision:source.aclRevision,sha256:source.sha256});return {parsed,source,chunks:parsed.status==='parsed'?chunkParsedDocument(parsed,{maxChars:retrieval.profile.limits.chunkChars}):[]};},
  async prepare({sources}){const s=scope();s.assertCurrent();const generation=documents.beginGeneration({tenant:s.tenant,sources,parser:parser.identity.parserVersion,chunker:parser.identity.chunkerVersion,embedding:retrieval.profile.representation,index:retrieval.identity.indexVersion});const ready=await retrieval.build({generation,principal:s.principal,activate:false});s.assertCurrent();return {handle:handle(generation,s.tenant),receipt:ready};},
  locate({sources}){const s=scope();s.assertCurrent();const generation=documents.beginGeneration({tenant:s.tenant,sources,parser:parser.identity.parserVersion,chunker:parser.identity.chunkerVersion,embedding:retrieval.profile.representation,index:retrieval.identity.indexVersion}),record=retrieval.inspect({tenant:s.tenant}).find(r=>r.id===generation.id);return {handle:handle(generation,s.tenant),status:record?.status??'not-dispatched',generationId:generation.id};},
  recover({id}){const s=scope();return handle(documents.recoverGeneration({id,tenant:s.tenant}),s.tenant);},
  activate(h){const {generation,tenant}=owned(h),s=scope();assert(s.tenant===tenant,'PermissionDenied','generation tenant');const result=retrieval.activate({generation,principal:s.principal});s.assertCurrent();return result;},
  inspect(h){const {generation}=owned(h);return documents.inspectGeneration(generation);},
  search({query,vector,topK=8}){const s=scope();s.assertCurrent();const result=retrieval.search({tenant:s.tenant,principal:s.principal,query,vector,topK});s.assertCurrent();return result;},
  retire({id}){const s=scope();s.assertCurrent();return retrieval.retire({tenant:s.tenant,generationId:id});},
 });originalIndexes.set(resource,{documents,retrieval,parser,scope});return resource;
}

/** Derived cache always retains the complete original model context, including
 * uncited sources. A hit consumes a fresh recipient/sink-bound source release. */
export function createKnowledgeCache({path,release,now=Date.now}){
 text(path,'knowledge cache path',4096);port(release,'source-release-port/v1',['recoverManifest','describeManifest','issueRelease','consumeRelease']);const db=new DatabaseSync(path);let closed=false;
 db.exec('PRAGMA busy_timeout=5000; CREATE TABLE IF NOT EXISTS knowledge_cache(key TEXT PRIMARY KEY,partition TEXT NOT NULL,manifest TEXT NOT NULL,dependencies TEXT NOT NULL,payload BLOB NOT NULL) STRICT;');
 const current=()=>assert(!closed,'StaleOwner','knowledge cache owner closed');
 const partition=(manifest,metadata)=>{const m=release.describeManifest(manifest),p=capture(metadata);for(const k of ['tenant','principal','recipient','sink','policyId','queryDigest','modelIdentity','promptDigest'])text(p[k],k,2048);assert(p.tenant===m.context.tenant&&p.principal===m.context.principal,'PermissionDenied','cache principal/source tenant');return {body:canonical({metadata:p,dependencies:m.entries}),metadata:p,dependencies:m.entries};};
 const exact=(metadata,payload,attemptId,fence)=>({policyId:metadata.policyId,attemptId,fence,resourceId:'knowledge-derived-output',action:metadata.action??'answer',sink:metadata.sink,recipient:metadata.recipient,payload,expiresAt:now()+30000,tenant:metadata.tenant,principal:metadata.principal});
 return Object.freeze({abi:'craft.knowledge-cache/v1',
  key({manifest,metadata}){current();return sha256(partition(manifest,metadata).body);},
  put({manifest,metadata,payload,fence}){current();const p=partition(manifest,metadata),content=copyBytes(payload,65536),request=exact(p.metadata,content,'cache-write:'+randomUUID(),fence),ticket=release.issueRelease({manifest,...request});release.consumeRelease(ticket,request);const key=sha256(p.body);db.prepare('INSERT INTO knowledge_cache VALUES(?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET manifest=excluded.manifest,dependencies=excluded.dependencies,payload=excluded.payload').run(key,p.body,manifest.id,canonical(p.dependencies),content);return freeze({key,manifestId:manifest.id,payloadSha256:sha256(content)});},
  release({key,metadata,fence}){current();const r=db.prepare('SELECT * FROM knowledge_cache WHERE key=?').get(key);if(!r)return null;const manifest=release.recoverManifest(r.manifest),p=partition(manifest,metadata);assert(p.body===r.partition&&sha256(p.body)===key,'PermissionDenied','cache actual recipient/sink/scope changed');const content=new Uint8Array(r.payload),request=exact(p.metadata,content,'cache-hit:'+randomUUID(),fence),ticket=release.issueRelease({manifest,...request});release.consumeRelease(ticket,request);return {wire:content,manifest,manifestId:manifest.id,payloadSha256:sha256(content)};},
  purgeSource({adapter,id}){current();let removed=0;for(const row of db.prepare('SELECT key,dependencies FROM knowledge_cache').all())if(JSON.parse(row.dependencies).some(s=>s.adapter===adapter&&s.id===id)){removed+=Number(db.prepare('DELETE FROM knowledge_cache WHERE key=?').run(row.key).changes);}return removed;},
  close(){if(!closed){closed=true;db.close();}},
 });
}

/** Generic protocol projection: only the original authored operation selects
 * Returned/Rejected/Failed and the business Decision. No native domain branch. */
export async function evaluateKnowledgeDecision({access,actor,id,run,request,proposal=null,proposalWire=null,receipt=null,candidateOrigin}){
 u64(id);u64(run);const result=await access.evaluate(actor,request),accepted=result.ok&&result.outcome.kind==='Returned';
 return freeze({id,run,accepted,reason:accepted?'accepted':result.ok?result.outcome.code:result.error.code,proposal,proposalWire,decision:accepted?result.outcome.value:null,receipt,...(candidateOrigin?{candidateOrigin}:{})});
}

const receipt=(status,providerId,contextManifest=null)=>({status,providerId,contextManifest,amountMinor:null,metrics:null});
const fullStorage=access=>{if(typeof access.assertStorageCurrent==='function')access.assertStorageCurrent();else access.assertCurrent();};
function sourceScope({gateway,snapshot,request,access}){const source=gateway.inspect(snapshot);return {tenant:source.principal.tenant,principal:source.principal.actor,fence:request.fence,approvalRevision:source.sources.approval?.revision??'0',deadline_ms:request.deadline_ms,assertCurrent(){request.assertCurrent();fullStorage(access);gateway.assertCurrent(snapshot);}};}
const parserFormat=p=>p.parsed.status==='parsed'?({'text/plain':'Text','text/markdown':'Markdown','application/pdf':'TextPdf'}[p.source.mediaType]):({'ENCRYPTED_PDF':'Encrypted','IMAGE_ONLY_OR_NO_TEXT':'ImageOnly'}[p.parsed.reason]??'Malformed');

/** Native extraction/index receipt projections feed the authored activation
 * decision; its selected CanActivate Rule alone permits the next stage. */
export function createIngestionApplicationHandlers({artifact,gateway,index,scope,prepareBinding,activateBinding,capabilities,release,policyId}){
 const bindings=new Map();
 const artifactCurrent=selectedKnowledgeArtifact(artifact),current=()=>{artifactCurrent();for(const cap of Object.values(capabilities))assert(typeof cap==='string'&&/^[a-f0-9]{64}$/.test(cap),'InvalidContract','actual selected knowledge artifact digest');};
 const prepare=method=>async ctx=>{const {actor,work,request,access}=ctx,snapshot=await gateway.load(actor,work);return scope.run(sourceScope({gateway,snapshot,request,access}),async()=>{
  const source=gateway.inspect(snapshot),ids=source.facts.sourceIds;assert(Array.isArray(ids)&&ids.length>0&&ids.length<=16&&new Set(ids).size===ids.length&&ids.every(id=>Object.values(source.sources).some(s=>s.id===id)),'ResourceLimit','bounded complete declared source list');
  const known=index.locate({sources:ids});if(method==='inspect'&&known.status==='not-dispatched')return {kind:'not-dispatched'};if(method==='inspect'&&!['ready','active'].includes(known.status))return {kind:'unknown'};
  const parsed=[];for(const id of ids)parsed.push(await index.parse({id}));
  const complete=parsed.every(p=>p.parsed.status==='parsed');assert(parsed.reduce((n,p)=>n+p.chunks.length,0)<=16,'ResourceLimit','selected authored chunk bound16 before any embedding dispatch');
  let built=null;if(complete)built=method==='execute'?await index.prepare({sources:ids}):{handle:known.handle,receipt:{generationId:known.generationId,status:known.status}};
  const chunks=parsed.flatMap(p=>p.chunks.map(c=>({documentVersion:c.source.version,contentDigest:sha256(c.text),embedded:!!built}))).map((c,i)=>({chunkId:String(i+1),...c}));assert(chunks.length<=16,'ResourceLimit','selected authored chunk bound16');
  const technical={parsed:complete,format:parserFormat(parsed.find(p=>p.parsed.status!=='parsed')??parsed[0]),state:complete?'Parsed':'Received',chunks,generation:source.facts.generation,expectedGeneration:source.facts.expectedGeneration,aclVersion:parsed[0].source.aclRevision,currentAclVersion:parsed[0].source.aclRevision};
  // Literal parser preview, never a fabricated model summary or OCR result.
  const proposal={subjectId:work.id,sourceVersion:source.sources.facts.revision,summary:[...parsed.map(p=>p.parsed.text).join('\n')].slice(0,512).join('')},wire=bytes(proposal),review=gateway.review(snapshot,{proposal,wire,technical});
  const value=await evaluateKnowledgeDecision({access,actor,id:work.id,run:work.run,request:review,proposal,proposalWire:Buffer.from(wire).toString('base64'),receipt:receipt(built?'ready':parsed[0].parsed.status,built?built.receipt.generationId:parsed[0].source.sha256,gateway.manifest(snapshot).id)});return {kind:'observed',value};
 });};
 bindings.set(prepareBinding,Object.freeze({capability_sha256:capabilities.prepare,assertCurrent:current,execute:prepare('execute'),inspect:prepare('inspect')}));
 const activate=async({actor,work,request,access})=>{const snapshot=await gateway.load(actor,work);return scope.run(sourceScope({gateway,snapshot,request,access}),async()=>{const previous=await access.stage(actor,work.run,1);assert(previous?.accepted&&previous.decision&&previous.receipt?.providerId&&previous.receipt.contextManifest,'SourceUnavailable','actual persisted source decision/context required');const original=release.recoverManifest(previous.receipt.contextManifest),source=gateway.inspect(snapshot),payload=bytes({generation:previous.receipt.providerId}),exact={policyId,attemptId:'index-activate:'+request.instance_sha256,fence:request.fence,resourceId:'knowledge-index',action:'index.activate',sink:source.target.sink,recipient:source.target.recipient,tenant:source.principal.tenant,principal:source.principal.actor,payload,expiresAt:Date.now()+30000},ticket=release.issueRelease({manifest:original,...exact});release.consumeRelease(ticket,exact);const generation=index.recover({id:previous.receipt.providerId}),observed=index.activate(generation);return {kind:'observed',value:{id:work.id,run:work.run,accepted:true,reason:'index-activated',proposal:previous.proposal,proposalWire:previous.proposalWire,decision:previous.decision,receipt:receipt(observed.status,observed.generationId,original.id)}};});};
 // Activation is a same-generation idempotent local commit, never paid I/O.
 bindings.set(activateBinding,Object.freeze({capability_sha256:capabilities.activate,assertCurrent:current,execute:activate,inspect:async ctx=>{const snapshot=await gateway.load(ctx.actor,ctx.work);return scope.run(sourceScope({gateway,snapshot,request:ctx.request,access:ctx.access}),async()=>{const previous=await ctx.access.stage(ctx.actor,ctx.work.run,1);assert(previous?.receipt?.providerId,'SourceUnavailable','prepared source generation receipt');const found=index.inspect(index.recover({id:previous.receipt.providerId}));return found.status==='active'?activate(ctx):{kind:'not-dispatched'};});}}));
 return bindings;
}

