 const review=async ctx=>{const snapshot=await gateway.load(ctx.actor,ctx.work);return scope.run(sourceScope({gateway,snapshot,request:ctx.request,access:ctx.access}),async()=>{const source=gateway.inspect(snapshot),ids=source.facts.sourceIds;assert(Array.isArray(ids)&&ids.length>0&&ids.length<=16&&new Set(ids).size===ids.length&&ids.every(id=>Object.values(source.sources).some(s=>s.id===id)),'InvalidContract','complete declared retirement source set');const handle=documents.port.beginGeneration({tenant:source.principal.tenant,sources:ids,parser:PARSER_IDENTITY.parserVersion,chunker:PARSER_IDENTITY.chunkerVersion,embedding:retrieval.profile.representation,index:retrieval.identity.indexVersion}),generation=documents.port.inspectGeneration(handle);inspectSources(generation,source.principal.actor);const first=gateway.readSource(snapshot,'documentA'),proposal={subjectId:ctx.work.id,sourceVersion:source.sources.facts.revision,summary:''},wire=bytes(proposal),technical={state:generation.status==='active'?'Active':'Received',format:{'application/pdf':'TextPdf','text/plain':'Text','text/markdown':'Markdown'}[first.mediaType],chunks:[],generation:source.facts.generation,expectedGeneration:source.facts.expectedGeneration,aclVersion:first.aclRevision,currentAclVersion:first.aclRevision,parsed:false},request=gateway.review(snapshot,{proposal,wire,technical}),value=await evaluateKnowledgeDecision({access:ctx.access,actor:ctx.actor,id:ctx.work.id,run:ctx.work.run,request,proposal,proposalWire:Buffer.from(wire).toString('base64'),receipt:receipt('retirement-reviewed',generation.id,gateway.manifest(snapshot).id)});return {kind:'observed',value};});};
 async function previous(ctx){const principal=await ctx.access.principal(ctx.actor,ctx.work.run),job=await ctx.access.job(ctx.actor,ctx.work.run),stage=await ctx.access.stage(ctx.actor,ctx.work.run,1);assert(job.id===ctx.work.id&&stage?.accepted&&stage.decision&&stage.receipt?.contextManifest&&stage.receipt.providerId,'SourceUnavailable','original generated retirement decision/receipt');const handle=documents.port.recoverGeneration({id:stage.receipt.providerId,tenant:principal.tenant}),generation=documents.port.inspectGeneration(handle),manifest=release.recoverManifest(stage.receipt.contextManifest),context=release.describeManifest(manifest);assert(context.context.tenant===principal.tenant&&context.context.principal===principal.actor,'PermissionDenied','same original retirement principal');return {principal,stage,generation,manifest};}
 const completed=(ctx,p)=>({kind:'observed',value:{...p.stage,id:ctx.work.id,run:ctx.work.run,reason:'retired',receipt:receipt('retired',p.generation.id,p.manifest.id)}});
 const inspect=async ctx=>{const p=await previous(ctx),states=inspectSources(p.generation,p.principal.actor),index=retrieval.inspect({tenant:p.principal.tenant}).find(g=>g.id===p.generation.id);ctx.request.assertCurrent();if((index?.status==='retired'||!index)&&states.every(s=>s==='deleted'))return completed(ctx,p);if((!index||['active','ready','building'].includes(index.status))&&states.every(s=>s==='current'))return {kind:'not-dispatched'};return {kind:'unknown',reason:'retirement-reconciliation-required'};};
 const execute=async ctx=>{const p=await previous(ctx),snapshot=await gateway.load(ctx.actor,ctx.work);assert(gateway.manifest(snapshot).id===p.manifest.id,'StaleOwner','original complete retirement context');const source=gateway.inspect(snapshot),fence=await ctx.access.openFence(ctx.actor,ctx.stage.entry,{id:ctx.work.id,run:ctx.work.run,stageAttempt:ctx.work.attempt},'knowledge-retire-'+ctx.request.instance_sha256);try{await fence.refresh();ctx.request.assertCurrent();const payload=bytes({generation:p.generation.id,sources:p.generation.sources}),exact={policyId,attemptId:'retire:'+ctx.request.instance_sha256,fence:ctx.request.fence,resourceId:'knowledge-index',action:'index.retire',sink:source.target.sink,recipient:source.target.recipient,tenant:p.principal.tenant,principal:p.principal.actor,payload,expiresAt:Date.now()+30000},ticket=release.issueRelease({manifest:p.manifest,...exact});release.consumeRelease(ticket,exact);fullStorage(ctx.access);assert(inspectSources(p.generation,p.principal.actor).every(s=>s==='current'),'StaleOwner','retirement must begin from exact live sources');if(retrieval.inspect({tenant:p.principal.tenant}).some(g=>g.id===p.generation.id))retrieval.retire({tenant:p.principal.tenant,generationId:p.generation.id});fullStorage(ctx.access);
  try{for(const expected of p.generation.sources){await fence.refresh();ctx.request.assertCurrent();fullStorage(ctx.access);for(const role of ['facts','approval']){const e=source.sources[role],actual=documents.port.read({id:e.id,tenant:p.principal.tenant,principal:p.principal.actor});assert(actual.revision===e.revision&&actual.aclRevision===e.aclRevision&&actual.sha256===e.sha256,'StaleOwner','retirement control source changed');}const actual=documents.port.read({id:expected.id,tenant:p.principal.tenant,principal:p.principal.actor});assert(actual.revision===expected.version&&actual.aclRevision===expected.acl_revision&&actual.sha256===expected.sha256,'StaleOwner','retirement exact source/version/ACL');documents.authority.delete({id:expected.id,tenant:p.principal.tenant,expected:{version:expected.version,aclRevision:expected.acl_revision,sha256:expected.sha256}});fullStorage(ctx.access);}}catch(cause){throw Object.assign(new Error('index retired; document tombstones require original-owner reconciliation'),{code:'RetirementReconciliationRequired',cause});}return completed(ctx,p);
 }finally{fence.close();}};
